let expect_error expected run=
  match run() with ()->failwith("Expected rejection: "^expected)
  |exception Diagnostic.Error error->require(error.message=expected)("Wrong rejection: "^error.message)
let expect_code expected run=
  match run() with ()->failwith("Expected diagnostic: "^expected)
  |exception Diagnostic.Error error->require(error.code=expected)("Wrong diagnostic: "^error.code)
let ()=
  List.iter(fun(id,text,fingerprint)->
    let raw=Json.parse text in let value,actual,size,clone=roundtrip raw in
    require(X.Codec.encode value=text)(id^": complete imported bytes differ");
    require(X.Codec.encode clone=text)(id^": typed constructor bytes differ");
    require(actual=fingerprint && size=String.length text)(id^": identity or size differs"))accepted;
  List.iter(fun(id,text,message)->
    try expect_error message(fun()->ignore(roundtrip(Json.parse text)))
    with Failure error->failwith(id^": "^error))rejected;
  let raw=Json.Object["é\n",Json.Array[Json.String "\001";Json.int 1;Json.Bool true]] in
  (* Python compact UTF-8 bytes, including escaped key and control character. *)
  let exact={document|{"é\n":["\u0001",1,true]}|document} in
  let size=X.Codec.measure raw in
  require(size.bytes=String.length exact && size.nodes=6) "Exact Unicode/escaped-key key+value accounting";
  let limits=X.Codec.make_limits ~max_bytes:size.bytes ~max_nodes:size.nodes () in
  require(X.Codec.encode ~limits raw=exact) "Exact reduced envelope must succeed";
  expect_code "verification_exploration_limit" (fun()->X.Codec.preflight ~limits:(X.Codec.make_limits ~max_bytes:(size.bytes-1)())raw);
  expect_code "verification_exploration_limit" (fun()->X.Codec.preflight ~limits:(X.Codec.make_limits ~max_nodes:(size.nodes-1)())raw);
  let rec cycle=Json.Array[cycle] in
  expect_code "verification_exploration_cycle" (fun()->X.Codec.preflight cycle);
  let rec spine=Json.Null::spine in
  expect_code "verification_exploration_limit" (fun()->X.Codec.preflight ~limits:(X.Codec.make_limits ~max_nodes:32())(Json.Array spine));
  expect_error "Exploration text must be valid UTF-8." (fun()->ignore(X.Observation.make ~signal_id:"\237\160\128"()));
  let entered=ref false in
  let limits=X.Codec.make_limits ~charge:(fun _->entered:=true;Diagnostic.fail "test_shared_work" "stop")() in
  expect_code "test_shared_work" (fun()->ignore(X.Observation.make ~limits ~signal_id:"signal"()));
  require !entered "Caller work hook was not used";
  (* The 64 MiB domain preflight accepts a shared string inventory beyond the
     inherited 32 MiB response ceiling without encoding or duplicating it. *)
  let block=String.make (4*1024*1024) 'x' in
  let larger=Json.Array(List.init 9(fun _->Json.String block)) in
  let larger_size=X.Codec.measure larger in
  require(larger_size.bytes>Limits.max_response_bytes) "Workflow aggregate retained the legacy 32 MiB ceiling";
  print_endline "verification workflow records: 11 full Python literals, 16 exact rejections and bounded codec tests passed"
